}

export function matchesLocationScopeV30(destination:V8Destination,scope:LocationScopeV30|null){
 if(!scope)return destination.countryCode==="GR";
 if(destination.countryCode!=="GR")return false;
 if(scope.selectedSlugs&&!scope.selectedSlugs.has(destination.slug))return false;
 return baseMatches(destination,scope.base??null);
}

export function locationScopeAuditV30(scope:LocationScopeV30|null){return scope?{id:scope.id,source:scope.source,labelEl:scope.labelEl,labelEn:scope.labelEn,outsideCountry:scope.outsideCountry??null}:null}

import { loadDestinationEvidence } from "@/lib/data/evidence-v12";
import type { DestinationEvidenceBundle } from "@/lib/decision/types";
import type { V8Ranked } from "@/lib/decision/v8-matcher";
import type { TripRequest } from "@/lib/validation/trip";

export type ResearchNeed = "ancient_history" | "dated_events";
export type ResearchIntent = { needs: Set<ResearchNeed>; explicit: boolean };

const norm = (value: string) => value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

export function researchIntent(request: TripRequest): ResearchIntent {
  const text = norm(request.tripText ?? "");
  const needs = new Set<ResearchNeed>();
  if (/αρχαι|αρχαιολογ|μνημει|ιστορικ.{0,12}(χωρ|τοπ)|ancient|archaeolog|historic site/.test(text)) needs.add("ancient_history");
  if (/εκδηλω|φεστιβαλ|συναυλι|παραστασ|event|festival|concert/.test(text)) needs.add("dated_events");
  return { needs, explicit: needs.size > 0 };
}

function textOf(bundle: DestinationEvidenceBundle) {
  return bundle.places.map(item => `${item.subjectName} ${item.headline} ${item.summary ?? ""}`).join(" ");
}

export function satisfiesResearchNeed(bundle: DestinationEvidenceBundle, need: ResearchNeed) {
  if (need === "dated_events") return bundle.hasDateMatchedEvents;
  return /αρχαι|αρχαιολογ|μνημει|ancient|archaeolog|monument|heritage/i.test(norm(textOf(bundle)));
}

export type ResearchScreen = {
  intent: ResearchIntent;
  evidence: Map<string, DestinationEvidenceBundle>;
  verifiedCoverage: Record<ResearchNeed, number>;
  ranked: V8Ranked[];
};

export async function screenResearchEvidence(request: TripRequest, ranked: V8Ranked[], limit = 18): Promise<ResearchScreen> {
  const intent = researchIntent(request);
  const evidence = new Map<string, DestinationEvidenceBundle>();
  const coverage: Record<ResearchNeed, number> = { ancient_history: 0, dated_events: 0 };
  if (!intent.explicit) return { intent, evidence, verifiedCoverage: coverage, ranked };
  const candidates = ranked.slice(0, limit);
  const bundles = await Promise.all(candidates.map(item => loadDestinationEvidence(item.destination.slug, request.startDate, request.endDate)));
  candidates.forEach((item, index) => evidence.set(item.destination.slug, bundles[index]));
  for (const need of intent.needs) coverage[need] = bundles.filter(bundle => satisfiesResearchNeed(bundle, need)).length;
  const rescored = ranked.map(item => {
    const bundle = evidence.get(item.destination.slug);
    if (!bundle) return item;
    let delta = 0;
    for (const need of intent.needs) delta += satisfiesResearchNeed(bundle, need) ? 14 : -10;
    return { ...item, score: Math.max(0, Math.min(100, item.score + delta)) };
  });
  return { intent, evidence, verifiedCoverage: coverage, ranked: rescored.sort((a, b) => b.score - a.score) };
}

import { V8_DIMENSIONS,type V8Dimension,type V8IntentProfile } from "@/lib/decision/v8-types";
import type { V8Ranked } from "@/lib/decision/v8-matcher";

const clamp=(v:number,min:number,max:number)=>Math.max(min,Math.min(max,v));
const index=Object.fromEntries(V8_DIMENSIONS.map((d,i)=>[d,i])) as Record<V8Dimension,number>;

export function semanticAdjustmentV18(item:V8Ranked,intent:V8IntentProfile){
 const semantic=intent.semantic;if(!semantic)return 0;let adjustment=0;
 for(const d of V8_DIMENSIONS){const negative=Math.max(0,Math.min(1,semantic.negative[d]??0));if(!negative)continue;const affinity=Math.max(0,Math.min(1,item.destination.vector[index[d]]??0));adjustment-=negative*affinity*16;if(negative>=.9&&affinity>=.85)adjustment-=5;}
 const q=semantic.qualifiers;if(q.avoidCrowds>0){const crowd=item.destination.crowdLevel;adjustment+=q.avoidCrowds*(crowd<=2?5:crowd===3?1:crowd===4?-5:-10);}
 if(q.easyAccess>0)adjustment+=q.easyAccess*clamp((item.breakdown.effort-72)/5,-8,6);
 if(q.slowRhythm>0){if(item.destination.tags.includes("relax"))adjustment+=3*q.slowRhythm;if(item.destination.tags.includes("nightlife"))adjustment-=4*q.slowRhythm;}
 // Walkability and local character are not asserted as destination facts here. Their positive influence is already represented conservatively through city/culture weights in the canonical intent contract.
 return clamp(adjustment,-24,12);
}

export function applySemanticIntentRankingV18(items:V8Ranked[],intent:V8IntentProfile){
 if(!intent.semantic)return items;return items.map(item=>{const adjustment=semanticAdjustmentV18(item,intent);return{...item,score:clamp(item.score+adjustment,0,100),preScore:clamp(item.preScore+adjustment,0,100)}}).sort((a,b)=>b.score-a.score);
}

import { loadV8StayOffers } from "@/lib/data/destination-v8";
import type { V8Recommendation, V8RecommendationResponse, V8StayOffer } from "@/lib/decision/v8-types";
